            return FfiConverterTypeSelectionGeometry.lift(
    callWithHandle {
    uniffiRustCallWithError(MobileFfiException) { _status ->
    UniffiLib.uniffi_word_mobile_ffi_fn_method_mobiledocumentsession_double_tap_at(
        it,
        
        FfiConverterUInt.lower(`pageIndex`),
        FfiConverterFloat.lower(`xPt`),
