/**
 * Error returned across the FFI boundary without panicking.
 */
sealed class MobileFfiException: kotlin.Exception() {
    
    class InvalidJson(
        
        val `detail`: kotlin.String
        ) : MobileFfiException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    class IoFailed(
        
        val `detail`: kotlin.String
        ) : MobileFfiException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    class CommandFailed(
        
        val `detail`: kotlin.String
        ) : MobileFfiException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    class InvalidPage(
        
        val `index`: kotlin.UInt, 
        
        val `count`: kotlin.UInt
        ) : MobileFfiException() {
        override val message
            get() = "index=${ `index` }, count=${ `count` }"
    }
    
    class InvalidTile(
        
        val `width`: kotlin.UInt, 
        
        val `height`: kotlin.UInt, 
        
        val `scale`: kotlin.Float
        ) : MobileFfiException() {
        override val message
            get() = "width=${ `width` }, height=${ `height` }, scale=${ `scale` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<MobileFfiException> {
        override fun lift(error_buf: RustBuffer.ByValue): MobileFfiException = FfiConverterTypeMobileFfiError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeMobileFfiError : FfiConverterRustBuffer<MobileFfiException> {
    override fun read(buf: ByteBuffer): MobileFfiException {
        

        return when(buf.getInt()) {
            1 -> MobileFfiException.InvalidJson(
                FfiConverterString.read(buf),
                )
            2 -> MobileFfiException.IoFailed(
                FfiConverterString.read(buf),
                )
            3 -> MobileFfiException.CommandFailed(
                FfiConverterString.read(buf),
                )
            4 -> MobileFfiException.InvalidPage(
                FfiConverterUInt.read(buf),
                FfiConverterUInt.read(buf),
                )
            5 -> MobileFfiException.InvalidTile(
                FfiConverterUInt.read(buf),
                FfiConverterUInt.read(buf),
                FfiConverterFloat.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: MobileFfiException): ULong {
        return when(value) {
            is MobileFfiException.InvalidJson -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is MobileFfiException.IoFailed -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is MobileFfiException.CommandFailed -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is MobileFfiException.InvalidPage -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterUInt.allocationSize(value.`index`)
                + FfiConverterUInt.allocationSize(value.`count`)
            )
            is MobileFfiException.InvalidTile -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterUInt.allocationSize(value.`width`)
                + FfiConverterUInt.allocationSize(value.`height`)
                + FfiConverterFloat.allocationSize(value.`scale`)
            )
        }
    }

    override fun write(value: MobileFfiException, buf: ByteBuffer) {
        when(value) {
            is MobileFfiException.InvalidJson -> {
                buf.putInt(1)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is MobileFfiException.IoFailed -> {
                buf.putInt(2)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is MobileFfiException.CommandFailed -> {
                buf.putInt(3)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is MobileFfiException.InvalidPage -> {
                buf.putInt(4)
                FfiConverterUInt.write(value.`index`, buf)
                FfiConverterUInt.write(value.`count`, buf)
                Unit
            }
            is MobileFfiException.InvalidTile -> {
                buf.putInt(5)
                FfiConverterUInt.write(value.`width`, buf)
                FfiConverterUInt.write(value.`height`, buf)
                FfiConverterFloat.write(value.`scale`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




/**
 * @suppress
 */
public object FfiConverterOptionalString: FfiConverterRustBuffer<kotlin.String?> {
    override fun read(buf: ByteBuffer): kotlin.String? {
        if (buf.get().toInt() == 0) {
            return null
        }
        return FfiConverterString.read(buf)
    }

    override fun allocationSize(value: kotlin.String?): ULong {
        if (value == null) {
            return 1UL
        } else {
            return 1UL + FfiConverterString.allocationSize(value)
        }
    }

    override fun write(value: kotlin.String?, buf: ByteBuffer) {
        if (value == null) {
            buf.put(0)
        } else {
            buf.put(1)
            FfiConverterString.write(value, buf)
        }
    }
}




